INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14601, 'Psalms 104:18', 'Psalms', 104, 18, '&nbsp;په لوړو غرونو کښې ځنګلى چېلۍ اوسيږى، په لويو ګړنګونو کښې د صحرا سوى اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14602, 'Psalms 104:19', 'Psalms', 104, 19, '&nbsp;تا سپوږمۍ د موسم د مقررولو دپاره جوړه کړه، نمر په دې پوهيږى چې کله ښکته شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14603, 'Psalms 104:20', 'Psalms', 104, 20, '&nbsp;تۀ تيارۀ راولې نو بيا شپه شى، او ټول ځنګلى ځناور په کښې په ګشت شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14604, 'Psalms 104:21', 'Psalms', 104, 21, '&nbsp;نو بيا ځوانان زمرى په خپل ښکار پسې غړمبيږى او د خُدائ پاک نه خپل خوراک غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14605, 'Psalms 104:22', 'Psalms', 104, 22, '&nbsp;خو چې کله د سحر نمر راښکاره شى، نو بيا هغوئ په خپلو غارونو کښې اودۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14606, 'Psalms 104:23', 'Psalms', 104, 23, '&nbsp;نو بيا بنى آدم خپلو کارونو پسې ځى، چې تر ماښامه خپله مزدورى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14607, 'Psalms 104:24', 'Psalms', 104, 24, '&nbsp;اے مالِکه خُدايه، تا د مختلفو ځناورو څومره قسمونه پېدا کړى دى، ټول دې په عقلمندۍ سره جوړ کړى دى، زمکه ستا د مخلوق نه ډکه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14608, 'Psalms 104:25', 'Psalms', 104, 25, '&nbsp;په دومره پراخه او لوئ سمندر کښې چې تا پېدا کړے دے. چې د بې‌شمېره مخلوق نه ډک دے، چې غټ او واړۀ ژوندى څيزونه په کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14609, 'Psalms 104:26', 'Psalms', 104, 26, '&nbsp;وګوره بيړۍ په کښې ځى راځى، سمندرى بلاګانې تا جوړې کړې چې په کښې لوبې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14610, 'Psalms 104:27', 'Psalms', 104, 27, '&nbsp;دا هر څۀ ستا نه طمع کوى چې دوئ ته په خپل وخت سره خوراک ورکړې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14611, 'Psalms 104:28', 'Psalms', 104, 28, '&nbsp;کله چې تۀ دوئ ته ورکوې نو دوئ يې راغونډوى، او چې خپل لاس کولاو کړې نو دوئ په ښۀ څيزونو ماړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14612, 'Psalms 104:29', 'Psalms', 104, 29, '&nbsp;نو کله چې تۀ د دوئ نه خپل مخ واړوې نو دوئ يريږى، کله چې تۀ د دوئ نه ساه واخلې نو دوئ مړۀ او دوباره خاورې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14613, 'Psalms 104:30', 'Psalms', 104, 30, '&nbsp;کله چې تۀ خپل روح راولېږې مخلوق راپېدا شى، او تۀ د زمکې مخ دوباره تازه کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14614, 'Psalms 104:31', 'Psalms', 104, 31, '&nbsp;د مالِک خُدائ جلال دې تر ابده قائم وى، مالِک خُدائ دې په خپل کار خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14615, 'Psalms 104:32', 'Psalms', 104, 32, '&nbsp;کله چې هغه زمکې ته وګورى نو په لړزان شى، او چې غرونو له لاس وروړى نو په لوګى بدل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14616, 'Psalms 104:33', 'Psalms', 104, 33, '&nbsp;زۀ به د مالِک خُدائ سندرې په خپل ټول ژوند کښې وايم، ترڅو چې ژوندے يم د خُدائ پاک ثناء به وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14617, 'Psalms 104:34', 'Psalms', 104, 34, '&nbsp;زما خيالونه او سوچونه دې هغه خوشحاله کړى، لکه چې زۀ په مالِک خُدائ کښې خوشحالى کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14618, 'Psalms 104:35', 'Psalms', 104, 35, '&nbsp;خو ګناهګاران دې د زمکې نه فنا شى او بدعمله دې نور پاتې نۀ شى. د مالِک خُدائ ثناء ووايه اے زما روحه. د مالِک خُدائ ثناء صِفت وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14619, 'Psalms 105:1', 'Psalms', 105, 1, '&nbsp;د مالِک خُدائ شُکر ګزارى وکړئ، او د هغۀ نوم واخلئ، کوم کارونه چې هغۀ کړى دى قومونه ترې خبر کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14620, 'Psalms 105:2', 'Psalms', 105, 2, '&nbsp;هغۀ ته سرود ووايئ او د هغۀ ثناء صِفت وکړئ، او د هغۀ ټول عجيبه کارونه وستايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14621, 'Psalms 105:3', 'Psalms', 105, 3, '&nbsp;تاسو د هغۀ په مقدس نوم فخر وکړئ، او د چا زړونه چې د مالِک خُدائ لټون کوى هغوئ دې خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14622, 'Psalms 105:4', 'Psalms', 105, 4, '&nbsp;د مالِک خُدائ او د هغۀ د طاقت لټون وکړئ، هر وخت د هغۀ د مخ د ليدو کوشش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14623, 'Psalms 105:5', 'Psalms', 105, 5, '&nbsp;کوم عجيبه کارونه چې هغۀ کړى دى هغه راپه ياد کړئ، او د هغۀ معجزې او اِنصاف ياد ساتئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14624, 'Psalms 105:6', 'Psalms', 105, 6, '&nbsp;اے د هغۀ د خِدمتګار اِبراهيم بچو، د هغۀ د غوره شوى د يعقوب بچو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14625, 'Psalms 105:7', 'Psalms', 105, 7, '&nbsp;هغه رب زمونږ خُدائ پاک دے، د هغۀ عدالت په ټوله دُنيا کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14626, 'Psalms 105:8', 'Psalms', 105, 8, '&nbsp;هغه خپل لوظ تر ابده پورې ياد ساتى، او هغه تر زر نسله پورې خپله وعده ياده ساتى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14627, 'Psalms 105:9', 'Psalms', 105, 9, '&nbsp;کوم لوظ چې هغۀ د اِبراهيم سره کړے وو، او هغه قسم چې دۀ د اِسحاق سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14628, 'Psalms 105:10', 'Psalms', 105, 10, '&nbsp;هغۀ دا د يعقوب دپاره اصُول جوړ کړو، او دا يې د بنى اِسرائيلو دپاره ابدى لوظ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14629, 'Psalms 105:11', 'Psalms', 105, 11, '&nbsp;هغۀ وفرمائيل، ”تاسو ته به زۀ د کنعان مُلک درکړم، لکه د خپل حق په شان به يې په ميراث کښې درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14630, 'Psalms 105:12', 'Psalms', 105, 12, '&nbsp;په کوم وخت کښې چې په شمار کښې دوئ ډېر کم وُو، او په حقيقت کښې هغوئ لږ او مسافر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14631, 'Psalms 105:13', 'Psalms', 105, 13, '&nbsp;دوئ به د يو قوم نه بل قوم ته سرګردانه ګرځېدل، او د يو بادشاهت نه به بل بادشاهت ته سرګردانه تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14632, 'Psalms 105:14', 'Psalms', 105, 14, '&nbsp;څوک يې هم نۀ پرېښودل چې په دوئ ظلم وکړى، تر دې چې د دوئ دپاره به يې بادشاهان رټل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14633, 'Psalms 105:15', 'Psalms', 105, 15, '&nbsp;هغه فرمائى، ”زما غوره شوو خلقو ته څۀ ونۀ وايئ، او نۀ زما پېغمبرانو ته نقصان ورسوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14634, 'Psalms 105:16', 'Psalms', 105, 16, '&nbsp;هغۀ په هغه زمکه باندې قحط نازل کړو، او د دوئ د خوراک وسيلې يې تباه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14635, 'Psalms 105:17', 'Psalms', 105, 17, '&nbsp;هغۀ د دوئ نه وړاندې يو سړے مِصر ته ولېږلو، يوسف څوک چې د يو غلام په شان خرڅ شولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14636, 'Psalms 105:18', 'Psalms', 105, 18, '&nbsp;د هغۀ پښې يې په بيړو خوږ کړې، د اوسپنو زنځير يې په غاړه ورته واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14637, 'Psalms 105:19', 'Psalms', 105, 19, '&nbsp;ترڅو چې د هغۀ پېشګوئې پوره شوې نۀ وه، د مالِک خُدائ کلام د هغۀ د زړۀ د رښتينوالى آزمېښت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14638, 'Psalms 105:20', 'Psalms', 105, 20, '&nbsp;نو بيا بادشاه هغه راوغوښتو او آزاد يې کړو، د قومونو بادشاه هغه آزاد کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14639, 'Psalms 105:21', 'Psalms', 105, 21, '&nbsp;هغۀ هغه د خپل کور مشر جوړ کړو، په خپل ټول ملکيت يې اختيار ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14640, 'Psalms 105:22', 'Psalms', 105, 22, '&nbsp;يوسف د بادشاه په آفسرانو باندې اختيار لرلو او د هغۀ مشيرانو ته يې تعليم ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14641, 'Psalms 105:23', 'Psalms', 105, 23, '&nbsp;نو بيا بنى اِسرائيل مِصر ته راننوتل، د حام په مُلک کښې يعقوب د مسافر په شان اوسېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14642, 'Psalms 105:24', 'Psalms', 105, 24, '&nbsp;خو مالِک خُدائ خپل خلق ډېر کړل، هغۀ دوئ د دشمنانو نه ډېر زيات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14643, 'Psalms 105:25', 'Psalms', 105, 25, '&nbsp;هغۀ د خپل قوم نه تور کړل د مِصريانو زړونه، چې د دۀ د خِدمتګارانو سره چالاکى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14644, 'Psalms 105:26', 'Psalms', 105, 26, '&nbsp;هغۀ خپل خِدمتګار موسىٰ ورولېږلو، او ورسره يې کوم چې هغۀ غوره کړے وو هارون ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14645, 'Psalms 105:27', 'Psalms', 105, 27, '&nbsp;نو هغوئ د خلقو په مخکښې د هغۀ عجيبه نښې ښکاره کړې، او عجيبه معجزې او نښې يې د حام په مُلک کښې ښکاره کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14646, 'Psalms 105:28', 'Psalms', 105, 28, '&nbsp;هغۀ تيارۀ راولېږله او مُلک يې ټول تورتم کړلو، خو ولې دوئ د هغۀ د کلام مخالفت وکړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14647, 'Psalms 105:29', 'Psalms', 105, 29, '&nbsp;او هغۀ د دوئ اوبۀ په وينو بدلې کړې، او د دوئ کبان يې په کښې مړۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14648, 'Psalms 105:30', 'Psalms', 105, 30, '&nbsp;د دوئ ټول مُلک د چيندخانو نه ډک شو، او تر دې چې د بادشاهانو په کمرو کښې ښکاره شول چيندخان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14649, 'Psalms 105:31', 'Psalms', 105, 31, '&nbsp;د هغۀ په حُکم راغلل د مچانو لښکرونه، او ورسره راغلل د ماشو لښکرونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14650, 'Psalms 105:32', 'Psalms', 105, 32, '&nbsp;د باران په ځائ ږلۍ ورباندې راغله، او ورسره په ټول مُلک کښې د برېښنا او تندر آوازونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14651, 'Psalms 105:33', 'Psalms', 105, 33, '&nbsp;هغۀ باغونه د انګورو اينځرانو ورله تباه کړل، او د هغوئ د ټول مُلک ونې يې راوغورزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14652, 'Psalms 105:34', 'Psalms', 105, 34, '&nbsp;هغۀ حُکم وکړُو او د قحط د مُولخانو راغلل لښکرونه، او ورسره وُو هم د نورو بې‌شمېره مُولخانو لښکرونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14653, 'Psalms 105:35', 'Psalms', 105, 35, '&nbsp;دوئ ورنه د مُلک ټول شنۀ بوټى وخوړل، او د دوئ د خاورې ټول پېداوار يې وخوړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14654, 'Psalms 105:36', 'Psalms', 105, 36, '&nbsp;نو بيا هغۀ په ټول مُلک کښې د هغوئ مشران زامن هلاک کړل، او د هغوئ د نارينتوب وړومبۍ مېوه يې تباه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14655, 'Psalms 105:37', 'Psalms', 105, 37, '&nbsp;هغۀ بنى اِسرائيل په سرو او سپينو زرو بار کړى راوويستل، او د هغوئ د قبيلو ټول خلق روغ رمټ پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14656, 'Psalms 105:38', 'Psalms', 105, 38, '&nbsp;په مِصر کښې ډېره خوشحالى وشوه د هغوئ په تلو، ځکه چې په هغوئ باندې دباؤ غورزېدلے وو د اِسرائيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14657, 'Psalms 105:39', 'Psalms', 105, 39, '&nbsp;د هغوئ د پټولو دپاره يې وريځ راخوره کړله، او اور يې راولېږلو چې شپه يې ورله رڼا کړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14658, 'Psalms 105:40', 'Psalms', 105, 40, '&nbsp;هغوئ ورته سوال وکړو او هغۀ دوئ ته مړَزان ورکړل، او هغوئ يې په آسمانى روټۍ ماړۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14659, 'Psalms 105:41', 'Psalms', 105, 41, '&nbsp;هغۀ ګټ په مينځ نيم کړو او اوبۀ ترې نه روانې شولې، لکه د سيند په شان په صحرا کښې وبهېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14660, 'Psalms 105:42', 'Psalms', 105, 42, '&nbsp;ځکه چې هغۀ ته خپله پاکه وعده ياده وه، کومه وعده چې هغۀ خپل خِدمتګار اِبراهيم سره کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14661, 'Psalms 105:43', 'Psalms', 105, 43, '&nbsp;هغۀ خپل خلق په ډيرې خوشحالۍ سره راوويستل، خپل غوره شوى خلق يې د خوشحالۍ په چغو او سورو سره راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14662, 'Psalms 105:44', 'Psalms', 105, 44, '&nbsp;هغۀ هغوئ له د نورو قومونو زمکه ورکړله، هغوئ ته هغۀ په ميراث کښې د نورو ګټه مفته ورکړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14663, 'Psalms 105:45', 'Psalms', 105, 45, '&nbsp;چې دوئ د هغۀ اصُول وساتى او د هغۀ قانون وپېژنى، ثناء دې مالِک خُدائ ته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14664, 'Psalms 106:1', 'Psalms', 106, 1, '&nbsp;د مالِک خُدائ ثناء صِفت وکړئ ځکه چې هغه ښۀ دے، د مالِک خُدائ شُکر ادا کړئ. د هغۀ مينه د تل دپاره پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14665, 'Psalms 106:2', 'Psalms', 106, 2, '&nbsp;د مالِک خُدائ د زورَورو کارونو بيان څوک کولے شى او څوک پوره د هغۀ ثناء صِفت بيانولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14666, 'Psalms 106:3', 'Psalms', 106, 3, '&nbsp;بختور دى هغوئ څوک چې اِنصاف کوى، او څوک چې تل ښۀ کارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14667, 'Psalms 106:4', 'Psalms', 106, 4, '&nbsp;په هغه وخت ما ياد ساته، اے مالِکه خُدايه، کله چې تۀ په خپلو خلقو رحم کوې، کله چې تۀ هغوئ بچ کوې نو زما مدد دپاره هم راشه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14668, 'Psalms 106:5', 'Psalms', 106, 5, '&nbsp;نو چې زۀ هم ستا د غوره شوو خلقو په برکتونو کښې شريک شم، او چې زۀ هم ستا د قوم په خوشحالۍ کښې برخه واخلم او چې زۀ ستا د خلقو سره په ثناء صِفت کولو کښې شريک شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14669, 'Psalms 106:6', 'Psalms', 106, 6, '&nbsp;مونږ هم د خپل پلار نيکۀ په شان ګناه ګار يُو، مونږ غلط کارونه وکړل او بدعمله يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14670, 'Psalms 106:7', 'Psalms', 106, 7, '&nbsp;کله چې زمونږ پلار نيکۀ په مِصر کښې وُو، نو ستا معجزو ته يې خيال ونۀ کړو، او ستا ډېر رحمونه ورته ياد نۀ وُو، او د بحرِقُلزم سره هغوئ بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14671, 'Psalms 106:8', 'Psalms', 106, 8, '&nbsp;خو بيا هم هغۀ د خپل نوم په خاطر هغوئ بچ کړۀ، د دې دپاره چې هغه په دې خپل طاقت څرګند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14672, 'Psalms 106:9', 'Psalms', 106, 9, '&nbsp;او هغۀ بحرِقُلزم ورټلو او هغه اوچ شو، هغۀ هغوئ په سمندر کښې داسې پورې ايستل لکه چې په صحرا کښې روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14673, 'Psalms 106:10', 'Psalms', 106, 10, '&nbsp;هغۀ دوئ د دشمنانو د لاسونو نه بچ کړل، او د دشمنانو د لاسونو نه يې په بيعه واخستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14674, 'Psalms 106:11', 'Psalms', 106, 11, '&nbsp;اوبو د هغوئ مخالفين ټول ډوب کړل، او په هغوئ کښې يو کس هم ژوندے پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14675, 'Psalms 106:12', 'Psalms', 106, 12, '&nbsp;بيا هغوئ د هغۀ په وعدو يقين شروع کړو د هغۀ د ثناء صِفت سرود يې ووئيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14676, 'Psalms 106:13', 'Psalms', 106, 13, '&nbsp;خو هغوئ هغه هر څۀ زر هېر کړل کوم چې خُدائ پاک د دوئ دپاره کړى وُو، او د هغۀ د نصيحت انتظار يې ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14677, 'Psalms 106:14', 'Psalms', 106, 14, '&nbsp;خو په هغه بيابان کښې دوئ شهوت پرستى شروع کړه، او په دې يې د خُدائ پاک صبر وآزمائيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14678, 'Psalms 106:15', 'Psalms', 106, 15, '&nbsp;نو بيا هغۀ هغوئ ته هر څۀ ورکړل کوم چې دوئ غوښتل، خو هغۀ ورسره وبا هم راولېږله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14679, 'Psalms 106:16', 'Psalms', 106, 16, '&nbsp;بيا هغوئ په کېمپ کښې د موسىٰ سره کينه وساتله او د هارون خلاف چې د مالِک خُدائ دپاره مقدس شوے وو کينه وکړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14680, 'Psalms 106:17', 'Psalms', 106, 17, '&nbsp;نو په دې وجه زمکه په مينځ وچاوده او داتن يې تير کړو، او ابيرام يې هم سره د نورو دوستانو تير کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14681, 'Psalms 106:18', 'Psalms', 106, 18, '&nbsp;او د دوئ د نورو مريدانو په مينځ کښې اور بل شو، او د اور په لمبې سره نور بدعمله تباه شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14682, 'Psalms 106:19', 'Psalms', 106, 19, '&nbsp;هغوئ په حورب يعنې سينا کښې سخے جوړ کړو او د اوسپنې نه د جوړ شوى بُت عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14683, 'Psalms 106:20', 'Psalms', 106, 20, '&nbsp;نو په دې کولو سره هغوئ جلالى خُدائ بدل کړو د يو سخى په شکل چې ګياه خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14684, 'Psalms 106:21', 'Psalms', 106, 21, '&nbsp;هغوئ خُدائ پاک يعنې خپل خلاصونکے هېر کړو، چا چې په مِصر کښې لوئ کارونه کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14685, 'Psalms 106:22', 'Psalms', 106, 22, '&nbsp;د حام په مُلک کښې يې معجزې وکړې او د بحرِقُلزم سره يې عجيبه کارنامې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14686, 'Psalms 106:23', 'Psalms', 106, 23, '&nbsp;نو هغۀ وفرمائيل زۀ به دوئ تباه کړم نو د هغۀ غوره شوى کس موسىٰ د خُدائ د غضب او مخلوق په مينځ کښې ودرېدلو چې د هغۀ غصه سړه او دوئ د تباهۍ نه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14687, 'Psalms 106:24', 'Psalms', 106, 24, '&nbsp;دوئ بيا د هغه ښۀ مُلک نه نفرت شروع کړو، او دوئ د هغۀ په وعده يقين نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14688, 'Psalms 106:25', 'Psalms', 106, 25, '&nbsp;هغوئ به په خپلو خېمو کښې غورېدل او د مالِک خُدائ تابعدارى يې ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14689, 'Psalms 106:26', 'Psalms', 106, 26, '&nbsp;نو هغۀ خپل لاس اوچت کړو او دوئ ته يې قسم وخوړو چې هغه به دوئ په دې دشته بيابان کښې مړۀ کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14690, 'Psalms 106:27', 'Psalms', 106, 27, '&nbsp;او د هغوئ اولاد يې په قومونو کښې خوارۀ کړل، او هغه يې په مُلکونو کښې تس نس کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14691, 'Psalms 106:28', 'Psalms', 106, 28, '&nbsp;هغوئ د بعل د فعور بُت عبادت وکړو او بُتانو ته د پېش کړے شوو قربانو غوښې يې وخوړلې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14692, 'Psalms 106:29', 'Psalms', 106, 29, '&nbsp;د هغوئ په بد عملونو مالِک خُدائ غصه شو، او په دوئ باندې يو لوئ مرض راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14693, 'Psalms 106:30', 'Psalms', 106, 30, '&nbsp;خو فينحاس ورمينځ ته شو او مخ نيوے يې وکړو، نو بيا مرض راقابو شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14694, 'Psalms 106:31', 'Psalms', 106, 31, '&nbsp;د دې کار په وجه هغه رښتينے جوړ شو دا به نسل در نسل تر ابده پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14695, 'Psalms 106:32', 'Psalms', 106, 32, '&nbsp;د مريبه د اوبو سره دوئ مالِک خُدائ غصه کړو، د دوئ په وجه په موسىٰ باندې مصيبت راغلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14696, 'Psalms 106:33', 'Psalms', 106, 33, '&nbsp;هغوئ د موسىٰ روح دومره خفه کړو، چې د هغۀ د خولې نه بې‌ځايه خبرې راووتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14697, 'Psalms 106:34', 'Psalms', 106, 34, '&nbsp;او هغوئ هغه قومونه هغه شان تباه نۀ کړل لکه څنګه چې مالِک خُدائ د هغوئ د وژلو حُکم کړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14698, 'Psalms 106:35', 'Psalms', 106, 35, '&nbsp;خو د دې په ځائ هغوئ هم په قومونو کښې ورګډ شول او د هغوئ رِواجونه يې خپل کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14699, 'Psalms 106:36', 'Psalms', 106, 36, '&nbsp;هغوئ د هغه خلقو د بُتانو عبادت وکړو، کوم چې د دوئ دپاره دام جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14700, 'Psalms 106:37', 'Psalms', 106, 37, '&nbsp;دوئ خپل زامن قربانى کړل او پيريانو ته يې خپلې لوڼه قربانى کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');